#!/usr/bin/env node
/**
 * Port of dataset/bech32/test14.py.
 *
 * Reads a comma separated list of integers plus three bit widths, regroups the
 * data from `--b` bit units into `--c` bit units, then again into `--d` bit
 * units, and prints both intermediate results.
 *
 *   node test14.mjs --a 165,53,183,4,81,215 --b 8 --c 5 --d 8
 *
 * The original is shipped as a frozen executable, so its `sys.argv[0]` -- and
 * therefore the program name argparse prints -- is `test14_executable`.
 */

import { ArgumentParser } from './lib/argparse/parser.mjs';
import { intType, strType } from './lib/argparse/types.mjs';
import * as bech32 from './lib/bech32/index.mjs';
import { frame, inFrame } from './lib/python/errors.mjs';
import { pyPrint } from './lib/python/io.mjs';
import { pyInt } from './lib/python/pyint.mjs';
import { runFrozenScript } from './lib/python/runtime.mjs';

const SCRIPT_FILE = 'test14.py';
const SCRIPT_STEM = 'test14';
const PROG = 'test14_executable';

/**
 * Frames of the original script.  The column offsets are those of the failing
 * expression on each line, which is what the caret line marks:
 *   line 12: `data = list(map(int, args.a.split(',')))`
 *   line 13: `step1 = bech32.convertbits(data, args.b, args.c)`
 *   line 14: `step2 = bech32.convertbits(step1, args.c, args.d)`
 *   line 19: `main()`
 */
const FRAMES = {
  module: frame({ file: SCRIPT_FILE, line: 19, func: '<module>', colno: 4, endColno: 10 }),
  parseData: frame({ file: SCRIPT_FILE, line: 12, func: 'main', colno: 11, endColno: 44 }),
  step1: frame({ file: SCRIPT_FILE, line: 13, func: 'main', colno: 12, endColno: 52 }),
  step2: frame({ file: SCRIPT_FILE, line: 14, func: 'main', colno: 12, endColno: 53 }),
};

function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.add_argument('--a', { type: strType, required: true }); // Data as comma-separated integers
  parser.add_argument('--b', { type: intType, required: true }); // From bits
  parser.add_argument('--c', { type: intType, required: true }); // Intermediate bits
  parser.add_argument('--d', { type: intType, required: true }); // To bits
  const args = parser.parse_args(process.argv.slice(2));

  const data = inFrame(FRAMES.parseData, () => args.a.split(',').map((piece) => pyInt(piece)));
  // Convert from bits to intermediate bits
  const step1 = inFrame(FRAMES.step1, () => bech32.convertbits(data, args.b, args.c));
  // Convert from intermediate to final bits
  const step2 = inFrame(FRAMES.step2, () => bech32.convertbits(step1, args.c, args.d));
  pyPrint(step1);
  pyPrint(step2);
}

runFrozenScript({ scriptStem: SCRIPT_STEM, moduleFrame: FRAMES.module, main });

