/**
 * The two output streams, written the way CPython writes them.
 *
 * `process.exitCode` is used instead of `process.exit()` throughout the port so
 * that pending writes on a pipe are always flushed before the process ends.
 */

import { reprValue } from './repr.mjs';

export function writeStdout(text) {
  process.stdout.write(text);
}

export function writeStderr(text) {
  process.stderr.write(text);
}

/** `print(value)`: the `repr()` of a container, `str()` of a plain string. */
export function pyPrint(value) {
  const text = typeof value === 'string' ? value : reprValue(value);
  writeStdout(`${text}\n`);
}

